-- Identity and organizations: Aurora DSQL target, not a deployed migration.
-- Execute each statement separately in order and checkpoint it. No enclosing
-- BEGIN: DSQL permits one DDL statement per transaction. After every INDEX
-- ASYNC, record job_id and wait for successful completion before proceeding.
-- See ../../../../design/identity/specification.md for normalization, authorization, and lifecycle rules.
-- IDs are generated by database identity sequences; inserts return generated IDs.
-- Retries use business uniqueness constraints, not preallocated identifiers.
-- public preserves the existing taxonomy interfaces; see namespace notes.

CREATE TABLE public.users (
    id bigint GENERATED BY DEFAULT AS IDENTITY (CACHE 1) PRIMARY KEY,
    cognito_issuer text NOT NULL CHECK (length(btrim(cognito_issuer)) > 0),
    cognito_subject text NOT NULL CHECK (length(btrim(cognito_subject)) > 0),
    email text NOT NULL CHECK (email = btrim(email) AND email <> ''),
    normalized_email text NOT NULL
        CHECK (normalized_email = lower(email) AND normalized_email <> ''),
    display_name text CHECK (display_name = btrim(display_name) AND display_name <> ''),
    created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    disabled_at timestamptz,
    auth_revision bigint NOT NULL DEFAULT 0 CHECK (auth_revision >= 0),
    CONSTRAINT users_cognito_identity_unique UNIQUE (cognito_issuer, cognito_subject),
    CHECK (updated_at >= created_at),
    CHECK (disabled_at IS NULL OR disabled_at >= created_at)
);

CREATE TABLE public.organizations (
    id bigint GENERATED BY DEFAULT AS IDENTITY (CACHE 1) PRIMARY KEY,
    name text NOT NULL CHECK (name = btrim(name) AND name <> ''),
    status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'active', 'archived')),
    created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    archived_at timestamptz,
    auth_revision bigint NOT NULL DEFAULT 0 CHECK (auth_revision >= 0),
    CHECK (updated_at >= created_at),
    CHECK ((status = 'archived') = (archived_at IS NOT NULL)),
    CHECK (archived_at IS NULL OR archived_at >= created_at)
);

CREATE TABLE public.organization_memberships (
    id bigint GENERATED BY DEFAULT AS IDENTITY (CACHE 1) PRIMARY KEY,
    organization_id bigint NOT NULL REFERENCES public.organizations(id) ON DELETE RESTRICT,
    user_id bigint NOT NULL REFERENCES public.users(id) ON DELETE RESTRICT,
    role text NOT NULL CHECK (role IN ('admin', 'editor', 'member')),
    joined_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    removed_at timestamptz,
    CONSTRAINT organization_membership_unique UNIQUE (organization_id, user_id),
    CHECK (updated_at >= joined_at),
    CHECK (removed_at IS NULL OR removed_at >= joined_at)
);

CREATE TABLE public.identity_audit_events (
    id bigint GENERATED BY DEFAULT AS IDENTITY (CACHE 1) PRIMARY KEY,
    organization_id bigint REFERENCES public.organizations(id) ON DELETE RESTRICT,
    actor_type text NOT NULL CHECK (actor_type IN ('user', 'operator', 'system')),
    actor_user_id bigint REFERENCES public.users(id) ON DELETE RESTRICT,
    actor_principal text,
    action text NOT NULL CHECK (length(btrim(action)) > 0),
    entity_type text NOT NULL CHECK (entity_type IN ('user', 'organization', 'membership')),
    entity_id bigint NOT NULL,
    occurred_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    details jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(details) = 'object'),
    request_id text NOT NULL CHECK (length(btrim(request_id)) > 0),
    CONSTRAINT identity_audit_actor CHECK (
        (actor_type = 'user' AND actor_user_id IS NOT NULL AND actor_principal IS NULL)
        OR (actor_type IN ('operator', 'system') AND actor_user_id IS NULL
            AND actor_principal IS NOT NULL AND length(btrim(actor_principal)) > 0))
);

CREATE INDEX ASYNC organization_memberships_user_idx
    ON public.organization_memberships(user_id, organization_id) WHERE removed_at IS NULL;
CREATE INDEX ASYNC organization_memberships_admin_idx
    ON public.organization_memberships(organization_id, user_id)
    WHERE removed_at IS NULL AND role = 'admin';
CREATE INDEX ASYNC identity_audit_organization_idx
    ON public.identity_audit_events(organization_id, occurred_at);
CREATE INDEX ASYNC identity_audit_entity_idx
    ON public.identity_audit_events(entity_type, entity_id, occurred_at);

-- No triggers, PL/pgSQL, domains, row-level security, or automatic cascades.
-- Cross-row/state-transition rules are specified as service transactions.
-- Apply permissions.sql with the deployment's dedicated non-owner DB roles.
